#pragma once
// Blood-power champion encounter; all summons and debuffs belong to this run.
class SaurfangRuntime final:public SourceRuntime,public ICC::SaurfangPort {
 Run& run;entt::entity boss;ICC::Saurfang controller;ICC::EventMap random;uint32_t now,last,nextMelee=0,nextMove=0;bool frenzy=false,berserk=false,failed=false;
 std::map<uint32_t,uint64_t> threat;std::set<uint32_t> marks;
 struct Debuff {uint32_t boilEnd=0,boilNext=0,runeEnd=0;};std::map<uint32_t,Debuff> debuffs;
 struct Beast {entt::entity actor;uint32_t target=0,next=0,born=0;bool scented=false;};std::vector<Beast> beasts;
 entt::entity Resolve(uint32_t pid){for(auto& m:run.members)if(m.pid==pid)return Player(m);return entt::null;}
 void Fx(uint32_t spell,int stage,entt::entity source,entt::entity target,Vec at,uint32_t life=1500,float radius=0){std::ostringstream line;line<<"er_dwfx "<<run.id<<' '<<run.nextHazard++<<' '<<spell<<' '<<stage<<' '<<(Valid(source)?P::GetPacketVID(source):0)<<' '<<(Valid(target)?P::GetPacketVID(target):0)<<' '<<BaseX+int(at.x*100)<<' '<<BaseY+int(at.y*100)<<' '<<life<<' '<<int(radius*100);Broadcast(run,line.str());}
 int64_t Value(uint32_t id,int64_t fallback){auto spell=ICC::Spells().Resolve(id,run.mode);if(!spell)return fallback;auto& e=spell->effects[0];return e.basePoints>0?int64_t(e.basePoints)+std::max(1,e.dieSides):fallback;}
 uint32_t Tank(){uint32_t result=0;double best=-1;for(auto p:Living(run)){auto pid=P::GetPlayerID(p);double score=double(threat[pid])+1/(1+Distance(Position(p),Position(boss)));if(!Due(now,debuffs[pid].runeEnd))score*=.05;if(score>best){best=score;result=pid;}}return result;}
 std::vector<entt::entity> Targets(bool ranged=false){auto list=Living(run);auto tank=Tank();list.erase(std::remove_if(list.begin(),list.end(),[&](auto p){return ranged&&P::GetPlayerID(p)==tank&&list.size()>1;}),list.end());for(size_t i=list.size();i>1;i--)std::swap(list[i-1],list[random.Uniform(0,uint32_t(i-1))]);return list;}
 void Damage(entt::entity p,int64_t amount,unsigned power,entt::entity source=entt::null){if(!Alive(run,p)||amount<=0)return;amount=amount*(100+controller.Power())/100*(berserk?6:1);CombatSystem::Damage(p,Valid(source)?source:boss,amount,DAMAGE_TYPE_SPECIAL);if(power)controller.Gain(*this,power);}
 void Heal(uint64_t amount){if(Valid(boss)&&!CombatSystem::IsDead(boss)){auto max=uint64_t(Points::GetMaxHP(boss));P::SetHP(boss,std::min<uint64_t>(max,uint64_t(std::max<int64_t>(0,P::GetHP(boss)))+amount));}}
 void Motion(uint8_t function){if(Valid(boss))M::SendMovePacket(boss,function,0,P::GetX(boss),P::GetY(boss),0);}
 void Release(){for(auto pid:marks){auto p=Resolve(pid);if(Present(run,p))Fx(72293,4,boss,p,Position(p));}for(auto& m:run.members)if(auto p=Player(m);Valid(p))AffectSystem::RemoveAffect(p,62045);}
public:
 explicit SaurfangRuntime(Run& r):run(r),boss(r.bosses.front()),controller(r.id^0x541),random(r.id^0x542),now(get_dword_time()),last(now){run.phase=1;controller.Reset(*this);Fx(72371,3,boss,boss,Position(boss),600000);Notice(run,"ER_BLOOD_BEGIN");}
 ~SaurfangRuntime()override{Release();}
 ICC::Difficulty Mode()const override{return run.mode;}
 void Ability(uint32_t spell)override{
  if(spell==72737||spell==26662){if(spell==72737)frenzy=true;else berserk=true;Fx(spell,3,boss,boss,Position(boss),600000);Notice(run,spell==72737?"ER_BLOOD_FRENZY":"ER_ENRAGE");return;}
  Motion(FUNC_MOB_SKILL);
  if(spell==72410){auto pid=Tank();auto p=Resolve(pid);if(Alive(run,p)){debuffs[pid].runeEnd=now+20000;Fx(spell,3,boss,p,Position(p),20000);Notice(run,"ER_BLOOD_RUNE");}return;}
  auto list=Targets(true);if(list.empty())return;
  if(spell==72385){auto count=std::min<size_t>(ICC::Raid25(run.mode)?3:1,list.size());for(size_t i=0;i<count;i++){auto p=list[i];auto& d=debuffs[P::GetPlayerID(p)];d.boilEnd=now+15000;d.boilNext=now+3000;Fx(spell,3,boss,p,Position(p),15000);}return;}
  if(spell==72380){auto point=Position(list.front());Fx(spell,5,boss,list.front(),point,1200,12);for(auto p:Living(run))if(Distance(Position(p),point)<=12)Damage(p,Value(spell,7600),2);Notice(run,"ER_BLOOD_NOVA");}
 }
 void SummonBeasts(unsigned count)override{auto list=Targets(true);if(list.empty())return;for(unsigned i=0;i<count&&beasts.size()<20;i++){float angle=6.2831853f*i/count;Vec at{Arenas[3].center.x+std::cos(angle)*8,Arenas[3].center.y+std::sin(angle)*8};auto e=Spawn(run,62026,at,1,0,38508);if(!Valid(e)){failed=true;continue;}beasts.push_back({e,P::GetPlayerID(list[i%list.size()]),now+1500,now,false});Fx(72172,2,boss,e,at,2000);}Notice(run,"ER_BLOOD_BEASTS");}
 void ScentOfBlood()override{for(auto& b:beasts)if(Valid(b.actor)&&!CombatSystem::IsDead(b.actor)){b.scented=true;Fx(72769,3,b.actor,b.actor,Position(b.actor),10000);}for(auto p:Living(run)){AffectSystem::RemoveAffect(p,62045);AffectSystem::AddAffect(p,62045,POINT_MOV_SPEED,-80,0,10,0,true);}Notice(run,"ER_BLOOD_SCENT");}
 bool MarkChampion()override{auto list=Targets(true);list.erase(std::remove_if(list.begin(),list.end(),[&](auto p){return marks.count(P::GetPlayerID(p));}),list.end());if(list.empty())return false;auto p=list.front();marks.insert(P::GetPlayerID(p));Fx(72293,3,boss,p,Position(p),600000);Aura(run,p,Mechanic::Mark,600000);Notice(run,"ER_BLOOD_MARK");return true;}
 void Attacked(entt::entity attacker,int64_t damage)override{auto pid=P::GetPlayerID(attacker);if(damage>0&&Participant(run,pid))threat[pid]+=uint64_t(damage);}
 int64_t TargetDamage(entt::entity,entt::entity victim,int64_t amount)override{for(auto& b:beasts)if(b.actor==victim)return amount;return amount;}
 void Died(entt::entity actor)override{auto pid=P::GetPlayerID(actor);if(pid&&marks.erase(pid)){Heal(uint64_t(Points::GetMaxHP(boss))*(ICC::Heroic(run.mode)?20:5)/100);Notice(run,"ER_BLOOD_MARK_DEATH");}if(pid){debuffs.erase(pid);AffectSystem::RemoveAffect(actor,62045);}}
 void Status(entt::entity p)override{ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_blood %u %u %u %u",run.id,controller.Power(),unsigned(marks.size()),frenzy?1:0);ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effects_clear 0");auto pid=P::GetPlayerID(p);if(marks.count(pid))ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effect 72293 1 0");auto& d=debuffs[pid];if(!Due(now,d.runeEnd))ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effect 72410 1 %u",(d.runeEnd-now+999)/1000);if(!Due(now,d.boilEnd))ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effect 72385 1 %u",(d.boilEnd-now+999)/1000);ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effects_end 0");}
 bool Update(uint32_t time)override{now=time;auto elapsed=now-last;last=now;if(!Valid(boss)||CombatSystem::IsDead(boss))return true;controller.Health(*this,unsigned(uint64_t(P::GetHP(boss))*100/std::max<int64_t>(1,Points::GetMaxHP(boss))));controller.Tick(*this,elapsed);run.resource=int(controller.Power());
  std::vector<uint32_t> boilTicks;for(auto& row:debuffs){auto& d=row.second;if(Alive(run,Resolve(row.first))&&d.boilEnd&&!Due(now,d.boilEnd)&&Due(now,d.boilNext)){d.boilNext=now+3000;boilTicks.push_back(row.first);}}for(auto pid:boilTicks)Damage(Resolve(pid),Value(72385,5000),1);
  auto p=Resolve(Tank());if(Alive(run,p)){auto distance=Distance(Position(p),Position(boss));if(distance>5&&Due(now,nextMove)){nextMove=now+750;if(Walk(run,Position(p)))M::Goto(boss,P::GetX(p),P::GetY(p));}else if(distance<=5&&Due(now,nextMelee)){nextMelee=now+(frenzy?1500:2000);M::Stop(boss);M::SetRotationToXY(boss,P::GetX(p),P::GetY(p));Motion(FUNC_ATTACK);auto damage=CalcMeleeDamage(boss,p);Damage(p,damage,0);if(!Due(now,debuffs[P::GetPlayerID(p)].runeEnd)){Heal(uint64_t(damage)*5);controller.Gain(*this,1);}for(auto pid:std::vector<uint32_t>(marks.begin(),marks.end())){auto target=Resolve(pid);if(Alive(run,target))Damage(target,Value(72255,4500),1);}}}
  for(size_t i=0;i<beasts.size();){auto& b=beasts[i];if(!Valid(b.actor)||CombatSystem::IsDead(b.actor)){Destroy(b.actor);beasts.erase(beasts.begin()+i);continue;}auto target=Resolve(b.target);if(!Alive(run,target)){auto list=Targets(true);b.target=list.empty()?0:P::GetPlayerID(list.front());target=Resolve(b.target);}if(Alive(run,target)&&Due(now,b.next)){b.next=now+(b.scented?1200:2000);if(Distance(Position(b.actor),Position(target))>2.5f){if(Walk(run,Position(target)))M::Goto(b.actor,P::GetX(target),P::GetY(target));}else{M::Stop(b.actor);M::SetRotationToXY(b.actor,P::GetX(target),P::GetY(target));M::SendMovePacket(b.actor,FUNC_ATTACK,0,P::GetX(b.actor),P::GetY(b.actor),0);Damage(target,CalcMeleeDamage(b.actor,target)*(b.scented?2:1),3,b.actor);}}if(b.scented&&now-b.born>20000)b.scented=false;++i;}
  return !failed;
 }
};
